import { drizzle } from "drizzle-orm/node-postgres";
import { Pool } from "pg";
import * as schema from "./schema";

// Neon on Vercel injects POSTGRES_URL next to DATABASE_URL; accept either.
const pool = new Pool({
  connectionString: process.env.DATABASE_URL ?? process.env.POSTGRES_URL,
});

export const db = drizzle(pool, { schema });
export { schema };

/**
 * A transaction handle, or the pool itself. Helpers that must be able to join
 * a caller's transaction take this rather than reaching for `db` directly.
 */
export type Tx = Parameters<Parameters<typeof db.transaction>[0]>[0] | typeof db;
---
import { execFileSync } from "node:child_process";
import { Client } from "pg";
import { ADMIN_URL, TEST_DB, TEST_DB_URL } from "./test-env";

/** Creates the test database and applies migrations once per `vitest` run. */
export async function setup() {
  const admin = new Client({ connectionString: ADMIN_URL });
  await admin.connect();
  const { rowCount } = await admin.query("SELECT 1 FROM pg_database WHERE datname = $1", [TEST_DB]);
  if (!rowCount) await admin.query(`CREATE DATABASE "${TEST_DB}"`);
  await admin.end();

  // Fresh schema every run: a half-applied migration from a previous run must
  // never be able to make a test pass or fail for the wrong reason.
  // The `drizzle` schema holds the migration journal — drop it too, or
  // drizzle-kit sees every migration as already applied and creates nothing.
  const db = new Client({ connectionString: TEST_DB_URL });
  await db.connect();
  await db.query("DROP SCHEMA IF EXISTS drizzle CASCADE;");
  await db.query("DROP SCHEMA public CASCADE; CREATE SCHEMA public;");
  await db.end();

  execFileSync("./node_modules/.bin/drizzle-kit", ["migrate"], {
    env: { ...process.env, DATABASE_URL: TEST_DB_URL },
    stdio: "inherit",
  });
}
import { TEST_DB_URL, TEST_REDIS_URL } from "./test-env";

// App modules build their Pool / Redis client at import time, so these must be
// set before any test file imports them. setupFiles run first, which is why
// this assignment lives here rather than inside a test.
process.env.DATABASE_URL = TEST_DB_URL;
process.env.REDIS_URL = TEST_REDIS_URL;
import { defineConfig } from "vitest/config";
import { fileURLToPath } from "node:url";

export default defineConfig({
  resolve: {
    alias: {
      "@": fileURLToPath(new URL("./src", import.meta.url)),
      // `server-only` throws unless it's inside Next's server bundle; under
      // vitest we are the server, so stub it out.
      "server-only": fileURLToPath(new URL("./src/test/server-only-stub.ts", import.meta.url)),
    },
  },
  test: {
    include: ["src/**/*.integration.test.ts"],
    globalSetup: ["src/test/global-setup.ts"],
    setupFiles: ["src/test/setup-integration.ts"],
    // Each file gets its own schema-truncating fixture; running files in
    // parallel against one database would make them fight over rows.
    fileParallelism: false,
    testTimeout: 30_000,
    hookTimeout: 60_000,
  },
});

