1	// Pure slot-generation engine: no DB, no Redis, fully unit-tested.
2	// All instants are UTC epoch ms; wall-clock times only exist relative to an
3	// IANA timezone, converted via Intl (no date libraries).
4	
5	export type Range = { startMs: number; endMs: number };
6	export type DayWindow = { open: string; close: string }; // "HH:MM" local wall time
7	
8	/** Offset of `timeZone` from UTC in minutes at the given instant (east positive). */
9	export function tzOffsetMinutes(timeZone: string, utcMs: number): number {
10	  const dtf = new Intl.DateTimeFormat("en-US", {
11	    timeZone,
12	    year: "numeric",
13	    month: "2-digit",
14	    day: "2-digit",
15	    hour: "2-digit",
16	    minute: "2-digit",
17	    second: "2-digit",
18	    hour12: false,
19	  });
20	  const parts: Record<string, number> = {};
21	  for (const { type, value } of dtf.formatToParts(utcMs)) {
22	    if (type !== "literal") parts[type] = Number(value);
23	  }
24	  const asUtc = Date.UTC(
25	    parts.year,
26	    parts.month - 1,
27	    parts.day,
28	    parts.hour === 24 ? 0 : parts.hour,
29	    parts.minute,
30	    parts.second,
31	  );
32	  return Math.round((asUtc - utcMs) / 60000);
33	}
34	
35	/** UTC instant of local wall time `HH:MM` on local date `YYYY-MM-DD` in `timeZone`. */
36	export function localTimeToUtc(dateISO: string, hhmm: string, timeZone: string): number {
37	  const [y, m, d] = dateISO.split("-").map(Number);
38	  const [hh, mm] = hhmm.split(":").map(Number);
39	  const naive = Date.UTC(y, m - 1, d, hh, mm);
40	  // Two-pass: estimate offset at the naive instant, then re-check at the
41	  // corrected instant so DST transitions resolve correctly.
42	  const offset1 = tzOffsetMinutes(timeZone, naive);
43	  const guess = naive - offset1 * 60000;
44	  const offset2 = tzOffsetMinutes(timeZone, guess);
45	  return naive - offset2 * 60000;
46	}
47	
48	/** ISO weekday (1 = Monday … 7 = Sunday) of local date `YYYY-MM-DD`. */
49	export function isoWeekday(dateISO: string): number {
50	  const [y, m, d] = dateISO.split("-").map(Number);
51	  const dow = new Date(Date.UTC(y, m - 1, d)).getUTCDay(); // 0=Sun
52	  return dow === 0 ? 7 : dow;
53	}
54	
55	const overlaps = (a: Range, b: Range) => a.startMs < b.endMs && b.startMs < a.endMs;
56	
57	export type SlotsInput = {
58	  dateISO: string; // local date at the business
59	  timeZone: string;
60	  window: DayWindow | null; // null = closed that day
61	  durationMin: number;
62	  stepMin?: number; // slot grid step, default 15
63	  busy?: Range[]; // confirmed bookings for the master
64	  holds?: Range[]; // active Redis holds for the master
65	  notBeforeMs?: number; // e.g. Date.now(): hide past slots
66	};
67	
68	/** Free slots for one master on one local day. */
69	export function slotsForDay(input: SlotsInput): Range[] {
70	  const { dateISO, timeZone, window, durationMin, stepMin = 15 } = input;
71	  if (!window) return [];
72	  const busy = [...(input.busy ?? []), ...(input.holds ?? [])];
73	  const openMs = localTimeToUtc(dateISO, window.open, timeZone);
74	  const closeMs = localTimeToUtc(dateISO, window.close, timeZone);
